={{ JSON.stringify({
  model: 'openai/gpt-6-luna',
  temperature: 0,
  messages: [
    { role: 'system', content: $('Set system prompt').first().json.systemPrompt },
    { role: 'user', content: 'Extract the order details from this message:\n\n' + $json.Order }
  ],
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'order',
      strict: true,
      schema: {
        type: 'object',
        properties: {
          eventName: { type: 'string' },
          eventDate: { type: 'string' },
          venue: { type: 'string' },
          pax: { type: 'string' },
          reportTime: { type: 'string' },
          startTime: { type: 'string' },
          dishes: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                name: { type: 'string' },
                sub: { type: 'string' },
                category: { type: 'string' },
                diet: { type: 'string', enum: ['V', 'N'] },
                dietConfidence: { type: 'string', enum: ['high', 'low'] }
              },
              required: ['name', 'sub', 'category', 'diet', 'dietConfidence'],
              additionalProperties: false
            }
          }
        },
        required: ['eventName', 'eventDate', 'venue', 'pax', 'reportTime', 'startTime', 'dishes'],
        additionalProperties: false
      }
    }
  },
  usage: { include: true }
}) }}

parameters.jsCode:
// The HTTP Request node returns OpenRouter's own chat-completion shape:
// choices[0].message.content is a JSON string (enforced by response_format),
// and (because the request set usage: { include: true }) a usage object with
// real token counts, appended to the final chunk/response.
const content = $json.choices[0].message.content;
const parsed = JSON.parse(content);
let dishes = (parsed.dishes || []).filter(d => d && d.name);
if (dishes.length === 0) throw new Error('No dishes found in the order text.');

// Egg named in the dish is non-veg, whatever the model said. The word
// boundary keeps "Eggless" and "Eggplant" veg.
const EGG = /\b(eggs?|anda|omelett?es?|omelets?)\b/i;
for (const d of dishes) if (EGG.test(d.name)) d.diet = 'N';

// Unless the form permits duplicates, keep only the first card per dish name.
const allowDuplicates = ($('On form submission').first().json['Duplicate Dishes'] || []).length > 0;
if (!allowDuplicates) {
  const seen = new Set();
  dishes = dishes.filter(d => {
    const key = d.name.trim().toLowerCase().replace(/\s+/g, ' ');
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

parsed.dishes = dishes;

// Dishes the model was unsure about, so they can be checked before printing.
const review = dishes
  .filter(d => d.dietConfidence === 'low')
  .map(d => d.name + ' (' + (d.diet === 'N' ? 'NON-VEG' : 'VEG') + ')');

const title = [parsed.eventName, parsed.eventDate, parsed.venue].filter(Boolean).join(' - ');

// "Order 5" -> order_5.pdf; no order number -> order_15_10_2026_12-12PM.pdf (IST).
const orderNo = ((parsed.eventName || '').match(/\d+/) || [])[0];
const fileName = (orderNo
  ? 'order_' + orderNo
  : 'order_' + DateTime.now().setZone('Asia/Kolkata').toFormat('dd_MM_yyyy_hh-mma')) + '.pdf';

// Same pricing / cache-rate the web app's usage note shows: $0.10 input,
// $0.01 cached input, $0.50 output per 1M tokens; ~95 USD->INR.
const usage = $json.usage || {};
const inTok = usage.prompt_tokens || 0;
const outTok = usage.completion_tokens || 0;
const totalTok = usage.total_tokens || (inTok + outTok);
const cachedTok = (usage.prompt_tokens_details && usage.prompt_tokens_details.cached_tokens) || 0;
const freshInTok = Math.max(0, inTok - cachedTok);
const costUsd = freshInTok / 1e6 * 0.10 + cachedTok / 1e6 * 0.01 + outTok / 1e6 * 0.50;
const costInr = costUsd * 95;
const usageNote = `Tokens: ${inTok} in + ${outTok} out = ${totalTok} total · Cost: $${costUsd.toFixed(4)} (₹${costInr.toFixed(2)})`;

return [{ json: { order: parsed, count: dishes.length, review, title: title || 'Dish Cards', fileName, parsedAt: Date.now(), usageNote } }];

// Both branches (Build replacements for Dish Cards, Build onepage for
// Onepage Poster) connect into this one node. Whichever branch actually ran
// is the only input this node ever receives, so it just passes that item
// through under one name — everything downstream references ONLY this
// node, never the two branches directly, so there is no more need to guess
// which of two possibly-unexecuted nodes produced the data.
return [{ json: $input.first().json }];

// Name the download after the order, not the sandbox's file path. Reads
// from Merge build output, which already picked whichever branch ran
// (Build replacements for Dish Cards, Build onepage for Onepage Poster).
const item = $input.first();
const built = $('Merge build output').first().json;
item.binary.data.fileName = built.fileName;
item.binary.data.mimeType = 'application/pdf';

// Where the time went. submittedAt is the form trigger's own stamp; parsedAt
// is set by whichever Build step ran right after its own work finishes.
const sec = (ms) => Math.round(ms / 100) / 10;
const now = Date.now();
const submittedAt = Date.parse($('On form submission').first().json.submittedAt);
const parsedAt = built.parsedAt;
const render = $('Run render.js').first().json;
const steps = (String(render.stdout || '').match(/TIMINGS (\{.*\})/) || [])[1];
item.json.timings = {
  totalSec: sec(now - submittedAt),
  aiParseSec: sec(parsedAt - submittedAt),
  e2bTotalSec: sec(now - parsedAt),
  renderCommandSec: sec(render.executionTimeMs || 0),
  renderStepsMs: steps ? JSON.parse(steps) : null,
};
item.json.review = built.review || [];
item.json.usageNote = built.usageNote || ''; // empty for Onepage Poster — no AI call, nothing to report
console.log('Soul Chef timings ' + JSON.stringify(item.json.timings));
return [item];

